# NVIDIA blog "NVIDIA AIStore at MLPerf Storage v3.0: Linear Scale-Out and Multi-Cloud Portability" held against storage/storage_v30_results.json and NVIDIA's system descriptions. python3 -I check_claims_storage_nvidia_v30.py
import json, hashlib, glob
FILES = ['storage/storage_v30_results.json']; YAMLS = sorted(glob.glob('storage/v3.0/closed/NVIDIA/systems/*.yaml'))
RAW = {f: open(f, 'rb').read() for f in FILES + YAMLS}
R = json.loads(RAW[FILES[0]])['rows']; NV = [r for r in R if r['submitter'] == 'NVIDIA' and r['division'] == 'closed']
def mk(i, q, calc, st, got, out, note): return dict(id=i, quote=q, calc=calc, stated=st, delivered=got, outcome=out, note=note, label_mismatch=False)
def row(sub, wl):
    m = [r for r in NV if r['submission_name'] == sub and r['workload'] == wl]; assert len(m) == 1, (sub, wl, len(m)); return m[0]
u3, u6, u12 = row('aistore-3n-oci-bm-denseio-e5-128-5client-unet3d', 'unet3d'), row('aistore-6n-oci-bm-denseio-e5-128-10client-unet3d', 'unet3d'), row('aistore-12n-oci-bm-denseio-e5-128-20client-unet3d', 'unet3d')
t3, t6, t12 = row('aistore-3n-oci-bm-denseio-e5-128-8client-405b-1t', 'llama3-1t'), row('aistore-6n-oci-bm-denseio-e5-128-8client-405b-1t', 'llama3-1t'), row('aistore-12n-oci-bm-denseio-e5-128-16client', 'llama3-1t')
r3, r6 = row('aistore-3n-oci-bm-denseio-e5-128-5client-retinanet', 'retinanet'), row('aistore-6n-oci-bm-denseio-e5-128-10client-retinanet', 'retinanet')
aws, gcp = row('aistore-3n-aws-i8ge-150g-4client-m8gn24xl-unet3d', 'unet3d'), row('aistore-3n-gcp-z3-200g-8client-n2d96', 'unet3d')
N = []
N.append(mk('AS1', 'NVIDIA published 20 Closed Division results across training and checkpointing workloads.', 'Closed division entries submitted by NVIDIA in the results repository', '20 Closed Division results', f'{len(NV)} Closed entries; categories {sorted({r["category"] for r in NV})}', 'CONSISTENT' if len(NV) == 20 else ('ABOVE' if len(NV) > 20 else 'BELOW'), 'Counted from the results repository.'))
a, b = u12['io_GiB_per_s'] / u3['io_GiB_per_s'], t12['read_GiB_per_s'] / t3['read_GiB_per_s']
N.append(mk('AS2', 'Increasing the AIStore cluster from 3 to 12 nodes (4x) delivered 3.97x the UNet3D training I/O and 3.99x the Llama 3 1T checkpoint recovery throughput', 'UNet3D I/O at 12 nodes over 3 nodes; Llama 3 1T load_checkpoint_io_mean at 12 nodes over 3 nodes', '3.97x and 3.99x', f'UNet3D {u12["io_GiB_per_s"]:.2f} over {u3["io_GiB_per_s"]:.2f} = {a:.3f}x. 1T read {t12["read_GiB_per_s"]:.2f} over {t3["read_GiB_per_s"]:.2f} = {b:.3f}x. The 1T runs used {t3["hosts"]} client nodes at 3 AIStore nodes and {t12["hosts"]} at 12.',
   'CONSISTENT' if (round(a, 2), round(b, 2)) == (3.97, 3.99) else 'CANNOT_TELL', 'Both ratios round to the stated figures. The client count was doubled for the 12 node checkpoint run, which the post states in its table.'))
pn = lambda r, n: r['io_GiB_per_s'] / n
N.append(mk('AS3', 'UNet3D throughput remained nearly constant per storage node: 9.72 GiB/s at three nodes, 9.70 GiB/s at six, and 9.63 GiB/s at twelve.', 'UNet3D I/O divided by AIStore node count', '9.72, 9.70 and 9.63 GiB/s per node', f'{pn(u3,3):.2f}, {pn(u6,6):.2f} and {pn(u12,12):.2f} GiB/s per node', 'CONSISTENT' if (round(pn(u3, 3), 2), round(pn(u6, 6), 2), round(pn(u12, 12), 2)) == (9.72, 9.70, 9.63) else 'CANNOT_TELL', 'Node counts taken from the submission names (3n, 6n, 12n).'))
g = r6['io_GiB_per_s'] / r3['io_GiB_per_s']
N.append(mk('AS4', 'From three to six OCI nodes, RetinaNet I/O increased from 27.09 to 50.04 GiB/s, a 1.85x gain.', 'RetinaNet I/O at 3 and 6 OCI nodes', '27.09 to 50.04 GiB/s, 1.85x', f'{r3["io_GiB_per_s"]:.2f} to {r6["io_GiB_per_s"]:.2f} GiB/s, {g:.3f}x', 'CONSISTENT' if (round(r3['io_GiB_per_s'], 2), round(r6['io_GiB_per_s'], 2), round(g, 2)) == (27.09, 50.04, 1.85) else 'CANNOT_TELL', 'Mean of the last five runs, as in every row.'))
N.append(mk('AS5', "Mean AU was 94.06% at three nodes and 89.25% at six nodes, both above the workload's 85% requirement.", 'RetinaNet accelerator utilization at 3 and 6 OCI nodes, against the 85% requirement stated in the post', '94.06% and 89.25%, both above 85%', f'{r3["au_pct"]:.2f}% and {r6["au_pct"]:.2f}%', 'CONSISTENT' if (round(r3['au_pct'], 2), round(r6['au_pct'], 2)) == (94.06, 89.25) and min(r3['au_pct'], r6['au_pct']) > 85 else 'CANNOT_TELL', 'The 85% requirement is as the post states it.'))
oci = row('aistore-3n-oci-bm-denseio-e5-128-5client-unet3d', 'unet3d'); per = [x['io_GiB_per_s'] / x['accelerators'] for x in (aws, gcp, oci)]
N.append(mk('AS6', 'I/O per simulated B200 stayed in a narrow range of 5.77 to 5.83 GiB/s.', 'UNet3D I/O divided by simulated accelerators on the three cloud deployments', '5.77 to 5.83 GiB/s', f'AWS {per[0]:.2f}, Google Cloud {per[1]:.2f}, OCI {per[2]:.2f} GiB/s per accelerator', 'CONSISTENT' if (round(min(per), 2), round(max(per), 2)) == (5.77, 5.83) else 'CANNOT_TELL', 'Accelerators are the simulated accelerator count in each entry.'))
aus = [x['au_pct'] for x in (aws, gcp, oci)]
N.append(mk('AS7', 'Three separate cloud deployments sustained more than 97% mean AU through the S3 object API.', 'UNet3D accelerator utilization on the AWS, Google Cloud and OCI entries, and their benchmark API', 'more than 97% mean AU, object API', f'{aus[0]:.2f}%, {aus[1]:.2f}%, {aus[2]:.2f}%; benchmark API {sorted({x["benchmark_API"] for x in (aws, gcp, oci)})}', 'CONSISTENT' if min(aus) > 97 else 'BELOW', 'The files record an object benchmark API. Whether it is S3 is as the post states.'))
nic = 100e9 / 8 / 2**30
N.append(mk('AS8', 'Each storage node had a nominal 100 Gb/s network interface, equivalent to 11.64 GiB/s before protocol overhead.', '100 Gb/s converted to GiB/s', '11.64 GiB/s', f'{nic:.3f} GiB/s', 'CONSISTENT' if round(nic, 2) == 11.64 else 'CANNOT_TELL', 'Arithmetic on the stated interface speed. The interface itself is not in the results files.'))
N.append(mk('AS9', 'Across twelve nodes, that provided 139.7 GiB/s of nominal aggregate NIC bandwidth.', '12 nodes at 100 Gb/s each', '139.7 GiB/s', f'{12 * nic:.2f} GiB/s', 'CONSISTENT' if round(12 * nic, 1) == 139.7 else 'CANNOT_TELL', 'Arithmetic on the stated interface speed.'))
N.append(mk('AS10', 'The benchmark delivered 136.54 GiB/s of recovery-read throughput and 133.27 GiB/s of write throughput, equivalent to 97.7% and 95.4% of that nominal figure, respectively.', 'Llama 3 1T summary at 12 nodes, read and write, divided by 12 times 11.64 GiB/s', '136.54 read, 133.27 write, 97.7% and 95.4%', f'{t12["read_GiB_per_s"]:.2f} read, {t12["write_GiB_per_s"]:.2f} write, {100 * t12["read_GiB_per_s"] / (12 * nic):.1f}% and {100 * t12["write_GiB_per_s"] / (12 * nic):.1f}%',
   'CONSISTENT' if (round(t12['read_GiB_per_s'], 2), round(t12['write_GiB_per_s'], 2), round(100 * t12['read_GiB_per_s'] / (12 * nic), 1), round(100 * t12['write_GiB_per_s'] / (12 * nic), 1)) == (136.54, 133.27, 97.7, 95.4) else 'CANNOT_TELL', 'Percentages use the exact nominal 139.70 GiB/s.'))
ratio = 140 * 1024 / 315
N.append(mk('AS11', 'RetinaNet has roughly 450 times as many objects per GiB as UNet3D, whose average sample is 140 MiB.', 'the post\'s own sizes: 140 MiB per UNet3D sample and about 315 KiB per RetinaNet object', 'roughly 450 times', f'{ratio:.0f} times', 'CONSISTENT' if abs(ratio - 450) / 450 < 0.05 else 'CANNOT_TELL', 'The object sizes are from the post, not the results files. The arithmetic is checked.'))
N.append(mk('AS12', 'The 1T-parameter model checkpoint runs used 8, 8, and 16 clients, respectively', 'client nodes (hosts) in the Llama 3 1T entries at 3, 6 and 12 AIStore nodes', '8, 8 and 16 clients', f'{t3["hosts"]}, {t6["hosts"]} and {t12["hosts"]} client nodes', 'CONSISTENT' if (t3['hosts'], t6['hosts'], t12['hosts']) == (8, 8, 16) else 'CANNOT_TELL', 'The rest of the sentence, two data-parallel instances at every scale, is not in the fields read here.'))
N.append(mk('AS13', 'The training runs scaled from 5 to 10 to 20 clients and simulated B200 accelerators', 'UNet3D entries at 3, 6 and 12 AIStore nodes, client nodes and simulated accelerators', '5, 10 and 20 clients and accelerators', f'hosts {u3["hosts"]}, {u6["hosts"]}, {u12["hosts"]}; accelerators {u3["accelerators"]}, {u6["accelerators"]}, {u12["accelerators"]}', 'CONSISTENT' if (u3['hosts'], u6['hosts'], u12['hosts'], u3['accelerators'], u6['accelerators'], u12['accelerators']) == (5, 10, 20, 5, 10, 20) else 'CANNOT_TELL', 'Read from the three UNet3D entries.'))
y48 = sum(1 for f in YAMLS if b'AIStore v4.8' in RAW[f]); yk = sum(1 for f in YAMLS if b'Kubernetes' in RAW[f])
N.append(mk('AS14', 'Our submission used NVIDIA AIStore v4.8 on Kubernetes.', 'NVIDIA system description files: AIStore version and Kubernetes', 'AIStore v4.8 on Kubernetes', f'{len(YAMLS)} system files. AIStore v4.8 appears in the description of {y48}. Kubernetes appears in {yk}.', 'CONSISTENT' if y48 > 0 and yk == len(YAMLS) else 'CANNOT_TELL', 'Counted from the yaml files. Where a file names Google Kubernetes Engine it counts as Kubernetes. ' + ('All files name it.' if yk == len(YAMLS) else 'One file, ' + [f for f in YAMLS if b'Kubernetes' not in RAW[f]][0].split('/')[-1] + ', does not name an orchestrator. The other ' + str(yk) + ' do, so the record is silent on that one entry and contradicts none.')))
ok = all(r['availability'] == 'available' and r['storage_location'] == 'remote' and r['benchmark_API'] == 'object' for r in NV)
N.append(mk('AS15', 'the submission is classified as Available, meaning all system components are publicly available, and as Shared Remote Object storage: multiple clients access the storage over a network through an object API.', 'availability, storage location and benchmark API on all NVIDIA Closed entries', 'Available; Shared Remote Object storage', f'availability {sorted({r["availability"] for r in NV})}, storage location {sorted({r["storage_location"] for r in NV})}, benchmark API {sorted({r["benchmark_API"] for r in NV})}', 'CONSISTENT' if ok else 'CANNOT_TELL', 'Read from the entry classifications.'))
N.append(mk('AS16', 'It was submitted to the Closed Division', 'division of NVIDIA entries', 'Closed Division', f'divisions {sorted({r["division"] for r in NV})}', 'CONSISTENT' if {r['division'] for r in NV} == {'closed'} else 'CANNOT_TELL', 'All 20 entries sit in the Closed folder.'))
N.append(mk('AS17', 'Cloud object storage was not part of the measured data path.', 'the results repository describes the system under test, not a negative about other storage', 'cloud object storage not in the measured data path', 'the files list AIStore nodes as the storage and name no other', 'CANNOT_TELL', 'A system description lists what was used. It does not state what was absent.'))
json.dump(dict(source=FILES + ['raw/nvidia_aistore_v30.txt'] + YAMLS, sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES + YAMLS], claims=N), open('claims_storage_nvidia_v30.json', 'w'), indent=1)
for c in N: print(c['id'], c['outcome'], '|', c['delivered'][:200])
